--region import
---@type ChatConstants
local ChatConstants = import('Game.OverseaChat.ChatConstants')
local Utf8 = require("Frame.utf8")
--endregion import

--region define
local UIModule = CS.Engine.UI.UIModule
local TextGenerator = CS.UnityEngine.TextGenerator
local Social = AppService:GetInstance():GetSocialLine()
---@type FriendComponent
local friendComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FriendComponent)
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaChat/OverseaChatBtnNode.prefab > name: OverseaChatBtnNode
---@class OverseaChatButtonNode
---@field Env                           	OverseaChatButtonNode                   
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field redPoint                      	UnityEngine.RectTransform               
---@field TxtTalk2                      	UnityEngine.RectTransform               
---@field TxtTalk1                      	UnityEngine.RectTransform               
---@field Mask                          	UnityEngine.Animation               
---@field Button                        	UnityEngine.RectTransform               
local OverseaChatButtonNode = Class("OverseaChatButtonNode")

--region lifecycle
function OverseaChatButtonNode:__init()
    self._cb = nil
    self._isUpper = true
    ---@type UnityEngine.Coroutine
    self._initCo = nil
    ---@type table<ChatConstants.Channel, boolean>
    self._channelFilter = nil
    ---@type UnityEngine.TextGenerator
    self.textGenerator = nil
end

function OverseaChatButtonNode:__delete()
    self._cb = nil
end

function OverseaChatButtonNode:Awake()
    self.textGenerator =  TextGenerator()
    self:InitHandler()

    if friendComp:HasFriendList() then
        self:InitView()
        return 
    end
    
    self._initCo = CoStart(function ()
        friendComp:SyncFriendList(function()
            self:InitView()
        end)
    end)
end

function OverseaChatButtonNode:Start()
end

function OverseaChatButtonNode:OnDestroy()
    self.textGenerator = nil
    if self._initCo then
        CoStop(self._initCo)
        self._initCo = nil
    end
    Events.RemoveListener(Constants.EventNames.OVERSEA_CHAT_NEW_MSG_PREVIEW, self._newMsgEvent)
    Events.RemoveListener(Constants.EventNames.OVERSEA_CHAT_REFRESH_MSG, self._refreshMsgEvent)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaChatButtonNode:InitHandler()
    SetButtonAction(self.Button, Bind(self, self.ButtonOnClickHandler))
    self._newMsgEvent = Events.AddListener(Constants.EventNames.OVERSEA_CHAT_NEW_MSG_PREVIEW, Bind(self, self.NewMsgEventHandler))
    self._refreshMsgEvent = Events.AddListener(Constants.EventNames.OVERSEA_CHAT_REFRESH_MSG, Bind(self, self.RefreshMsgEventHandler))
end

function OverseaChatButtonNode:InitView()
    self:InitRedPoint()
    self:RefreshText()
end

function OverseaChatButtonNode:InitRedPoint()
    local isHave = Social:IsHaveUnreadMsgByPlayerId()
    GameUtils.BindRedPoint(Constants.RedPointConst.OverseaChat, self.Button.gameObject, true)
    if isHave then
        GameUtils.SetRedPointNum(Constants.RedPointConst.OverseaChat, 1)
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.OverseaChat)
    end
end
--endregion init

--region handler
---按钮点击回调
function OverseaChatButtonNode:ButtonOnClickHandler()
    if self._cb then
        self._cb()
        return 
    end
    
    -- 默认的点击处理
    UIModule.OpenDialog({id = Constants.UITypeIds.OverseaChatMainDialog})
end

---收到新的消息
function OverseaChatButtonNode:NewMsgEventHandler()
    self:RefreshText()
end

--- 刷新消息显示
function OverseaChatButtonNode:RefreshMsgEventHandler()
    self:ClearText()
    self:RefreshText()
end
--endregion handler

--region public
---设置按钮点击回调
---@param callback fun(event:table):void
function OverseaChatButtonNode:SetButtonCallback(callback)
    self._cb = callback
end

---设置频道过滤
---@param channels ChatConstants.Channel[] @ 显示的频道列表
function OverseaChatButtonNode:SetChannelFilter(channels)
    local ChannelList = checkTable(channels)
    if not next(ChannelList) then return end
    
    local filter = {}
    for _, v in ipairs(ChannelList) do
        filter[v] = true
    end
    self._channelFilter = filter
    -- 更改后要清理当前的显示内容
    self:ClearText()
    self:RefreshText()
end
--endregion public

--region private
---刷新text
function OverseaChatButtonNode:RefreshText()
    local data = Social.previewData
    if not next(data) then return end
    
    if self._channelFilter and not self._channelFilter[data.channel] then return end

    if data.channel == ChatConstants.Channels.World and not GameUtils.IsChatWorldOpen() then return end

    local node = nil
    if self._isUpper then
        node = self.TxtTalk1
    else
        node = self.TxtTalk2
    end
    
    local channelName = nil
    local playerName = ""
    if data.channel == ChatConstants.Channels.Private then
        channelName = localize("私聊")
        playerName = tostring(data.name) .. ":"
    elseif data.channel == ChatConstants.Channels.Fight then
        channelName = localize("战斗")
        playerName = tostring(data.name) .. ":"
    elseif data.channel == ChatConstants.Channels.Union then
        channelName = localize("工会")
        playerName = tostring(data.name) .. ":"
    elseif data.channel == ChatConstants.Channels.World then
        channelName = localize("世界")
        playerName = tostring(data.name) .. ":"
    elseif data.channel == ChatConstants.Channels.System then
        channelName = localize("系统")
        data.text = Social:ConvertSystemMessage(data.data) -- 重新获取一次，避免在初始语言前生效
    elseif data.channel == ChatConstants.Channels.CrossWorld then
        channelName = localize("跨服")
        playerName = tostring(data.name) .. ":"
    end
    local text = tostring(data.text)
    text = string.gsub(text, "^#%[%d+%]#$", localize("[表情]"))
    text = self:SetTextWithEllipsis(node, channelName, playerName, text)
    CfUtils.FillText(node, string.format('<color=#22fcff>[%s]</color><color=#e8feff>%s%s</color>', channelName, playerName, text))
    
    self.Mask:Stop()
    if self._isUpper then
        CfUtils.PlayAnimation(self.Mask, "UIHomeView_Chat_TxtTalk1_Show")
    else
        CfUtils.PlayAnimation(self.Mask, "UIHomeView_Chat_TxtTalk2_Show")
    end
    self._isUpper = not self._isUpper
end

---清空当前显示
function OverseaChatButtonNode:ClearText()
    CfUtils.FillText(self.TxtTalk1, '')
    CfUtils.FillText(self.TxtTalk2, '')
end

---超出部分用省略号替换
function OverseaChatButtonNode:SetTextWithEllipsis(textNode, channelName, playerName, text)
    -- gsub里是不是没有或运算符啊，先这么写吧
    text = string.gsub(text, "<%/?color=?#?%w*>", '')
    text = string.gsub(text, "<%/?size=?#?%w*>", '')
    text = string.gsub(text, "<%/?b>", '')
    text = string.gsub(text, "<%/?i>", '')
    local content = string.format("[%s]%s%s", channelName, playerName, text)
    --local generator = CS.UnityEngine.TextGenerator();
    local textComp = textNode.gameObject:GetComponent(typeof(CS.UnityEngine.UI.Text))
    local settings = textComp:GetGenerationSettings(textNode.rect.size);
    if isNull(textComp) then return text end

    CfUtils.FillText(textNode, content)
    if self.textGenerator then
        self.textGenerator:Populate(content, settings)
        local characterCountVisible = self.textGenerator.characterCountVisible
        local updatedText = content
        if utf8.len(updatedText) > characterCountVisible then
            updatedText = Utf8.sub(updatedText, 1, characterCountVisible)
            updatedText = string.gsub(updatedText, string.format("%%[%s%%]%s", channelName, playerName), "")
            updatedText = updatedText .. "…"
            return updatedText
        else
            return text
        end
    else
        return text
    end
end
--endregion private

return OverseaChatButtonNode